#!/usr/bin/env bash
set -euo pipefail
s="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"; bash -n "$s/deploy.sh" "$s/install.sh" "$s/check.sh"; grep -q 'FROM mautic/mautic:7.2-apache@sha256:' "$s/Dockerfile"; grep -q 'symfony/dom-crawler:7.4.17' "$s/Dockerfile"; grep -q 'docker-php-ext-install.*imap' "$s/Dockerfile"; grep -q 'nginx:1.28.0-alpine@sha256:' "$s/compose.yml"; grep -q 'MAUTIC_RUN_CRON_JOBS' "$s/compose.yml"; grep -q 'MAUTIC_MAILER_DSN' "$s/compose.yml"; grep -q 'DOCKER_MAUTIC_ROLE: mautic_cron' "$s/compose.yml"; grep -q 'DOCKER_MAUTIC_ROLE: mautic_worker' "$s/compose.yml"; grep -q 'DOCKER_MAUTIC_WORKERS_CONSUME_FAILED: "0"' "$s/compose.yml"; grep -q 'owner_marketing_egress' "$s/compose.yml"; grep -Fq 'profiles: ["owner-marketing-cron"]' "$s/compose.yml"; grep -Fq 'profiles: ["owner-marketing-worker"]' "$s/compose.yml"; grep -q 'internal: true' "$s/compose.yml"; grep -q 'proxy_pass http://mautic:80' "$s/nginx.conf"; grep -q 'mautic:install' "$s/install.sh"; grep -q 'MAUTIC_PUBLIC_URL' "$s/install.sh"; grep -q 'configure_site.sh' "$s/deploy.sh"; grep -q 'configure_site.sh' "$s/check.sh"; grep -Fq '$parameters["site_url"] = $expected' "$s/configure_site.sh"; grep -q 'MAUTIC_RUNTIME_PROFILES' "$s/deploy.sh"; grep -q '18106' "$s/compose.yml"; echo 'owner-marketing static tests passed'
